import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Features', role: 'headline', typography: { fontSize: 96 } },
    ];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const headlineText = (headlineItem?.text ?? 'Features').replace(/[^\x00-\x7F]/g, '');
  const headlineFontSize = headlineItem?.typography?.fontSize ?? 96;

  const group = new Group();
  group.name = 'features-title';

  // --- backdrop plane: engineered gradient + subtle grain -------------------
  const atlasRect = { w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;
  const planeHeight = 1.6;
  const planeWidth = planeHeight * aspect;

  const planeGeo = new PlaneGeometry(planeWidth, planeHeight, 1, 1);
  const planeMat = new MeshBasicNodeMaterial({ transparent: true });

  // static engineered gradient fallback (before grain texture resolves)
  const gradientNode = mix(color(colors.ink), color(colors.surface), uv().y);
  planeMat.colorNode = gradientNode;
  planeMat.opacity = 0.0;

  const planeMesh = new Mesh(planeGeo, planeMat);
  planeMesh.position.set(0, 0, 0);
  group.add(planeMesh);

  let grainTexture = null;
  const grainUrl = config.imageUrl;
  if (grainUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader
      .loadTexture(grainUrl)
      .then((tex) => {
        grainTexture = tex;
        const grainSample = texture(tex, uv());
        // subtle grain: blend the gradient with a small amount of grain modulation
        const grainInfluence = mix(gradientNode, gradientNode.mul(grainSample), 0.18);
        planeMat.colorNode = grainInfluence;
        planeMat.needsUpdate = true;
      })
      .catch(() => {
        // leave gradient-only fallback in place
      });
  }

  // --- headline text ----------------------------------------------------
  const textObj = ctx.fontAtlas.createText(headlineText, {
    fontSize: headlineFontSize,
    color: colors.paper,
    align: 'center',
  });
  textObj.position.set(0, 0, 0.02);
  group.add(textObj);

  // --- entrance motion: weighted-settle + fade-up ------------------------
  group.position.y += 0.2;
  group.scale.setScalar(0.96);
  planeMat.opacity = 0;
  textObj.traverse?.((child) => {
    if (child.material) {
      child.material.transparent = true;
      child.material.opacity = 0;
    }
  });
  if (textObj.material) {
    textObj.material.transparent = true;
    textObj.material.opacity = 0;
  }

  const tl = gsap.timeline();
  tl.to(group.position, { y: group.position.y - 0.2, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(planeMat, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.05);
  tl.to(
    group.scale,
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' },
    0.0
  );
  tl.to(
    { v: 0 },
    {
      v: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: function () {
        const val = this.targets()[0].v;
        if (textObj.material) textObj.material.opacity = val;
        textObj.traverse?.((child) => {
          if (child.material) child.material.opacity = val;
        });
      },
    },
    0.15
  );

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    planeGeo.dispose();
    planeMat.dispose();
    if (grainTexture && grainTexture.dispose) grainTexture.dispose();
    textObj.traverse?.((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (child.material.map && child.material.map.dispose) child.material.map.dispose();
        child.material.dispose();
      }
    });
    group.clear();
  };

  return group;
}
